const toast=(message)=>{const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(window.vaaniToast);window.vaaniToast=setTimeout(()=>el.classList.remove('show'),2600)};document.querySelectorAll('[data-demo-download]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();toast('Demo audio link — connect storage to download the MP3')}));
